import{_ as t,o,c as a,ae as s}from"./chunks/framework.Dn6zxbF8.js";const d=JSON.parse('{"title":"URL Path Design","description":"","frontmatter":{"id":"8702033095","title":"URL Path Design","state":"Approved","created":"2021-12-13T00:00:00.000Z","tags":["seo","url","openapi"],"category":"Platform"},"headers":[],"relativePath":"adrs/8702033095/README.md","filePath":"adrs/8702033095/README.md"}'),r={name:"adrs/8702033095/README.md"};function n(i,e,l,u,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="url-path-design" tabindex="-1">URL Path Design <a class="header-anchor" href="#url-path-design" aria-label="Permalink to &quot;URL Path Design&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The lack of alignment in URL design across products causes multiple issues in software development.</p><p>Suboptimal SEO where some Search Engines don&#39;t recognize underscores in URLs. A URL containing &quot;my_page&quot; will be indexed as &quot;my page&quot; (as one term) while a URL containing &quot;my-page&quot; will be indexed as &quot;my&quot; &quot;page&quot; (as two terms).</p><p>Worth saying that this is primarily how Google Search Engine does things, regardless, it is safe to say that it is prudent following Google Search optimizations.</p><p>Suboptimal user-experience since camelCase and underscore also require the user to use the shift key, whereas hyphenated does not on desktop keywords; and characters like underscore are hidden behind special symbols in mobile phones keywords.</p><p>Lack of shared tooling, forcing developers to reimplement tools or promoting bikeshedding.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><blockquote><p>These rules apply to URL Paths. URL Query Params have their own rules.</p></blockquote><p>Creating &quot;perfect software&quot; is close to impossible. The following suggestions may feel like suggestions because we don&#39;t have the full scope of the situation.</p><p>Therefore, you <strong>MAY</strong> follow the following resolutions unless you have a technical limitation. You <strong>MUST</strong> assumed such rules de facto in conversations.</p><p>You <strong>MUST</strong> use the following characters anywhere in the path:</p><ul><li>U+0061 to U+007A (&quot;a-z&quot;)</li><li>U+0030 to U+0039 (&quot;0-9&quot;)</li><li>U+007E (&quot;~&quot;)</li><li>U+002E (&quot;.&quot;)</li><li>U+0080 and above (non-ASCII Unicode characters; not recommended, not URL safe)</li></ul><p>You <strong>MAY</strong> use the following characters are allowed in path, except as the first or last character:</p><ul><li><p>U+002D HYPHEN-MINUS, &quot;-&quot;</p></li><li><p>U+005F LOW LINE, &quot;_”</p></li><li><p>You <strong>MUST</strong> separate terms using hyphen character</p></li><li><p>You <strong>MUST</strong> use underscore for new compound words or composed terms</p></li><li><p>You <strong>MUST</strong> use non-reserved characters, URL safe characters specified in <a href="https://datatracker.ietf.org/doc/html/rfc3986#page-13" target="_blank" rel="noreferrer">RFC 3986</a></p></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=AQcSFsQyct8&amp;ab_channel=GoogleSearchCentral" target="_blank" rel="noreferrer">Underscores vs. dashes in URLs</a></li><li><a href="https://developers.google.com/search/docs/advanced/guidelines/url-structure" target="_blank" rel="noreferrer">Keep a simple URL structure</a></li></ul>',17)])])}const g=t(r,[["render",n]]);export{d as __pageData,g as default};
